package com.ekayn.api.service;

import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.repo.UserRepository; import com.ekayn.api.security.JwtService; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;

class AuthServiceTest {
  @Mock UserRepository users; @Mock org.springframework.security.crypto.password.PasswordEncoder encoder; @Mock JwtService jwt; @Mock NotificationService notifications; @Mock AuthRateLimiter limiter; AuthService service;
  @BeforeEach void setup(){MockitoAnnotations.openMocks(this);service=new AuthService(users,encoder,jwt,notifications,limiter);when(encoder.encode(anyString())).thenReturn("hash");when(users.save(any())).thenAnswer(inv->inv.getArgument(0));when(jwt.create(any(),anyString(),anyString(),anyLong())).thenReturn("jwt");}
  @Test void registrationAlwaysCreatesCustomerAndDoesNotReturnJwtInProfile(){when(users.findByEmailIgnoreCase(anyString())).thenReturn(Optional.empty());Auth result=service.register(new Register("client@example.test","password123","A","Client"));assertEquals("CUSTOMER",result.user().role());assertEquals("jwt",result.token());verify(notifications).verification(any(User.class),anyString());}
  @Test void verificationTokenIsSingleUse(){when(users.findByVerificationTokenHash(anyString())).thenReturn(Optional.empty());assertThrows(IllegalArgumentException.class,()->service.verify("unknown"));}
  @Test void unverifiedUserCannotLogin(){User user=new User();user.setPasswordHash("hash");user.setEmailVerified(false);when(users.findByEmailIgnoreCase(anyString())).thenReturn(Optional.of(user));when(encoder.matches("password123","hash")).thenReturn(true);IllegalArgumentException error=assertThrows(IllegalArgumentException.class,()->service.login(new Login("client@example.test","password123")));assertEquals("Vérifiez votre adresse email avant de vous connecter.",error.getMessage());verifyNoInteractions(jwt);}
  @Test void verifiedUserReceivesJwt(){User user=new User();user.setId(UUID.randomUUID());user.setEmail("client@example.test");user.setPasswordHash("hash");user.setEmailVerified(true);when(users.findByEmailIgnoreCase(anyString())).thenReturn(Optional.of(user));when(encoder.matches("password123","hash")).thenReturn(true);Auth result=service.login(new Login("client@example.test","password123"));assertEquals("jwt",result.token());verify(jwt).create(user.getId(),user.getEmail(),user.getRole().name(),user.getSessionVersion());}
}
